async function callClaude(prompt) {
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 1000,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  const data = await res.json();
  const text = (data.content || [])
    .map((b) => (b.type === "text" ? b.text : ""))
    .filter(Boolean)
    .join("\n")
    .trim();
  if (!text) throw new Error("AI返回为空,请重试");
  return text;
}

function buildContext(c) {
  const msgs = (c.messages || []).slice(-30);
  const lines = msgs.map((m) => `${m.dir === "in" ? "客户" : "我方"}:${m.text}`).join("\n");
  return `客户档案:姓名 ${c.name},地区 ${c.region || "未知"},客户阶段 ${c.stage},意向等级 ${c.intent},标签:${(c.tags || []).join("、") || "无"},内部备注:${c.notes || "无"}
最近对话记录("客户"为对方,"我方"为我们的销售):
${lines || "(尚无对话,这将是我方发出的第一条消息)"}`;
}

export default function SalesWorkbench() {
  const [data, setData] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [activeId, setActiveId] = useState(null);
  const [search, setSearch] = useState("");
  const [msgInput, setMsgInput] = useState("");
  const [sendAs, setSendAs] = useState("me");
  const [sug, setSug] = useState({ status: "idle", reply: "", note: "", error: "" });
  const [fu, setFu] = useState({ status: "idle", text: "", error: "" });
  const [translating, setTranslating] = useState({});
  const [showSettings, setShowSettings] = useState(false);
  const [settingsDraft, setSettingsDraft] = useState({ productKb: "", playbook: "" });
  const [showAdd, setShowAdd] = useState(false);
  const [addForm, setAddForm] = useState({ name: "", phone: "", region: "" });
  const [tagInput, setTagInput] = useState("");
  const [toast, setToast] = useState("");
  const saveTimer = useRef(null);
  const toastTimer = useRef(null);
  const chatRef = useRef(null);

  useEffect(() => {
    (async () => {
      try {
        const r = await window.storage.get("swb:data");
        if (r && r.value) {
          const parsed = JSON.parse(r.value);
          setData(parsed);
          if (parsed.customers && parsed.customers[0]) setActiveId(parsed.customers[0].id);
        } else {
          setData(SEED);
          setActiveId(SEED.customers[0].id);
        }
      } catch (e) {
        setData(SEED);
        setActiveId(SEED.customers[0].id);
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  const showToast = (msg) => {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 2600);
  };

  const persist = (next) => {
    setData(next);
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        await window.storage.set("swb:data", JSON.stringify(next));
      } catch (e) {
        showToast("云端保存失败,数据暂存在本页");
      }
    }, 400);
  };

  const active = data && data.customers.find((c) => c.id === activeId);

  useEffect(() => {
    if (chatRef.current) chatRef.current.scrollTop = chatRef.current.scrollHeight;
  }, [activeId, active && active.messages.length]);

  const updateCust = (id, patch) => {
    const next = {
      ...data,
      customers: data.customers.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    };
    persist(next);
  };

  const send = () => {
    const text = msgInput.trim();
    if (!text || !active) return;
    const m = { id: uid(), dir: sendAs === "me" ? "out" : "in", text, ts: now() };
    updateCust(active.id, { messages: [...active.messages, m] });
    setMsgInput("");
    if (sendAs === "me" && sug.status === "ready") setSug({ status: "idle", reply: "", note: "", error: "" });
  };

  const genSuggestion = async () => {
    if (!active || sug.status === "loading") return;
    setSug({ status: "loading", reply: "", note: "", error: "" });
    const prompt = `你是一家外贸公司的金牌销售(销冠),正在通过WhatsApp跟进客户。请基于以下资料,给出下一条最应该发给客户的回复。

【产品知识库】
${data.settings.productKb}

【销冠打法与范例】
${data.settings.playbook}

【当前客户】
${buildContext(active)}

要求:
1. 回复语言与客户最近一条消息的语言保持一致;若尚无对话,用英文写开场白
2. WhatsApp风格:口语化、自然、简短(一般不超过80词)
3. 不得承诺知识库以外的价格、折扣、交期;涉及时说明以正式报价单为准
4. 每条回复都要推动对话进展(补齐关键信息、寄样、报价、约通话等)

只返回JSON,不要任何其他文字和markdown标记:{"reply":"要发送的回复原文","note":"一句话中文说明这条回复的销售思路"}`;
    try {
      const raw = await callClaude(prompt);
      const clean = raw.replace(/```json|```/g, "").trim();
      let obj;
      try {
        obj = JSON.parse(clean);
      } catch (e) {
        obj = { reply: clean, note: "" };
      }
      setSug({ status: "ready", reply: obj.reply || clean, note: obj.note || "", error: "" });
    } catch (e) {
      setSug({ status: "error", reply: "", note: "", error: String(e.message || e) });
    }
  };

  const translateMsg = async (msg) => {
    if (!active || translating[msg.id]) return;
    setTranslating((t) => ({ ...t, [msg.id]: true }));
    try {
      const zh = await callClaude(`请把下面这条消息翻译成简体中文,只返回译文,不要任何解释:\n${msg.text}`);
      updateCust(active.id, {
        messages: active.messages.map((m) => (m.id === msg.id ? { ...m, zh } : m)),
      });
    } catch (e) {
      showToast("翻译失败,请重试");
    } finally {
      setTranslating((t) => {
        const n = { ...t };
        delete n[msg.id];
        return n;
      });
    }
  };

  const genFollowUp = async () => {
    if (!active || fu.status === "loading") return;
    setFu({ status: "loading", text: "", error: "" });
    const prompt = `你是销售助理。请根据以下客户档案和对话,生成一条中文跟进纪要,格式如下(每项一行,简洁):
【沟通要点】...
【客户态度】...
【主要异议】...(没有则写"无")
【下一步动作】...(具体、可执行)

${buildContext(active)}

只返回纪要正文,不要其他内容。`;
    try {
      const text = await callClaude(prompt);
      setFu({ status: "ready", text, error: "" });
    } catch (e) {
      setFu({ status: "error", text: "", error: String(e.message || e) });
    }
  };

  const saveFollowUp = () => {
    if (!active || !fu.text.trim()) return;
    updateCust(active.id, {
      followUps: [{ id: uid(), ts: now(), content: fu.text.trim() }, ...(active.followUps || [])],
    });
    setFu({ status: "idle", text: "", error: "" });
    showToast("跟进纪要已保存");
  };

  const addTag = () => {
    const t = tagInput.trim();
    if (!t || !active) return;
    if ((active.tags || []).includes(t)) {
      setTagInput("");
      return;
    }
    updateCust(active.id, { tags: [...(active.tags || []), t] });
    setTagInput("");
  };

  const addCustomer = () => {
    const name = addForm.name.trim();
    if (!name) {
      showToast("请填写客户姓名");
      return;
    }
    const c = {
      id: uid(),
      name,
      phone: addForm.phone.trim(),
      region: addForm.region.trim(),
      stage: "新进线",
      intent: "C",
      tags: [],
      notes: "",
      followUps: [],
      messages: [],
    };
    persist({ ...data, customers: [c, ...data.customers] });
    setActiveId(c.id);
    setShowAdd(false);
    setAddForm({ name: "", phone: "", region: "" });
  };

  if (!loaded || !data) {
    return (
      <div className="h-screen flex items-center justify-center bg-stone-100 text-stone-500 text-sm">
        正在加载工作台…
      </div>
    );
  }

  const list = data.customers.filter(
    (c) => !search.trim() || c.name.toLowerCase().includes(search.trim().toLowerCase()) || (c.phone || "").includes(search.trim())
  );

  return (
    <div className="h-screen flex flex-col bg-stone-100 text-stone-800" style={{ fontFamily: "system-ui, -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif" }}>
      <div className="flex items-center gap-3 px-4 py-2.5 bg-white border-b border-stone-200 shrink-0">
        <div className="flex items-baseline gap-2">
          <span className="text-base font-semibold tracking-tight">销冠工作台</span>
          <span className="text-xs text-stone-400">AI销转系统 · 原型 v0.1</span>
        </div>
        <span className="ml-2 text-xs px-2 py-0.5 rounded-full bg-amber-50 text-amber-700 border border-amber-200">
          WhatsApp通道:模拟中(正式版接入真实通道)
        </span>
        <div className="ml-auto flex items-center gap-2">
          <button
            onClick={() => {
              setSettingsDraft({ productKb: data.settings.productKb, playbook: data.settings.playbook });
              setShowSettings(true);
            }}
            className="text-xs px-3 py-1.5 rounded-lg border border-stone-300 hover:bg-stone-50"
          >
            知识库设置
          </button>
        </div>
      </div>

      <div className="flex-1 flex min-h-0">
        <div className="w-64 bg-white border-r border-stone-200 flex flex-col shrink-0">
          <div className="p-3 border-b border-stone-100 flex gap-2">
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="搜索客户"
              className="flex-1 text-sm px-2.5 py-1.5 rounded-lg border border-stone-200 bg-stone-50 focus:outline-none focus:border-emerald-400"
            />
            <button
              onClick={() => setShowAdd(true)}
              className="px-2.5 py-1.5 rounded-lg bg-emerald-600 text-white text-sm hover:bg-emerald-700"
              title="新增客户"
            >
              +
            </button>
          </div>
          <div className="flex-1 overflow-y-auto">
            {list.length === 0 && (
              <div className="p-4 text-xs text-stone-400">暂无客户,点右上角 + 新增</div>
            )}
            {list.map((c) => {
              const last = c.messages[c.messages.length - 1];
              return (
                <div
                  key={c.id}
                  onClick={() => {
                    setActiveId(c.id);
                    setSug({ status: "idle", reply: "", note: "", error: "" });
                    setFu({ status: "idle", text: "", error: "" });
                  }}
                  className={`px-3 py-2.5 cursor-pointer border-b border-stone-50 hover:bg-stone-50 ${c.id === activeId ? "bg-emerald-50" : ""}`}
                >
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] px-1.5 py-0.5 rounded border font-semibold ${INTENT_STYLE[c.intent]}`}>{c.intent}</span>
                    <span className="text-sm font-medium truncate">{c.name}</span>
                    <span className="ml-auto text-[10px] text-stone-400 shrink-0">{c.stage}</span>
                  </div>
                  <div className="mt-1 text-xs text-stone-400 truncate">
                    {last ? `${last.dir === "in" ? "客户: " : "我: "}${last.text}` : "尚无对话"}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="flex-1 flex flex-col min-w-0 bg-stone-50">
          {!active ? (
            <div className="flex-1 flex items-center justify-center text-sm text-stone-400">
              从左侧选择一个客户,或新增客户开始
            </div>
          ) : (
            <>
              <div className="px-4 py-2.5 bg-white border-b border-stone-200 flex items-center gap-3">
                <div>
                  <div className="text-sm font-semibold">{active.name}</div>
                  <div className="text-xs text-stone-400">{active.phone || "未填电话"} · {active.region || "未填地区"}</div>
                </div>
              </div>

              <div ref={chatRef} className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
                {active.messages.length === 0 && (
                  <div className="text-center text-xs text-stone-400 mt-8">
                    尚无对话。可切换到"客户消息(模拟)"录入一条客户来消息,再让AI给你销冠建议。
                  </div>
                )}
                {active.messages.map((m) => (
                  <div key={m.id} className={`flex ${m.dir === "out" ? "justify-end" : "justify-start"}`}>
                    <div className={`max-w-[70%] rounded-2xl px-3.5 py-2 text-sm leading-relaxed ${m.dir === "out" ? "bg-emerald-600 text-white rounded-br-sm" : "bg-white border border-stone-200 rounded-bl-sm"}`}>
                      <div className="whitespace-pre-wrap break-words">{m.text}</div>
                      {m.zh && (
                        <div className={`mt-1.5 pt-1.5 text-xs whitespace-pre-wrap ${m.dir === "out" ? "border-t border-emerald-500 text-emerald-100" : "border-t border-violet-100 text-violet-700"}`}>
                          AI译:{m.zh}
                        </div>
                      )}
                      <div className={`mt-1 flex items-center gap-2 text-[10px] ${m.dir === "out" ? "text-emerald-200" : "text-stone-400"}`}>
                        <span>{fmtTime(m.ts)}</span>
                        {!m.zh && (
                          <button
                            onClick={() => translateMsg(m)}
                            className={`underline ${m.dir === "out" ? "hover:text-white" : "text-violet-500 hover:text-violet-700"}`}
                          >
                            {translating[m.id] ? "翻译中…" : "AI译"}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="px-4 pb-3 pt-1 bg-stone-50">
                {sug.status !== "idle" && (
                  <div className="mb-2 rounded-xl border border-violet-200 bg-violet-50 p-3">
                    <div className="flex items-center gap-2 text-xs font-semibold text-violet-700">
                      <span>AI销冠建议</span>
                      {sug.status === "loading" && <span className="font-normal text-violet-500">正在通读上下文并生成…</span>}
                    </div>
                    {sug.status === "error" && (
                      <div className="mt-1 text-xs text-rose-600">{sug.error}</div>
                    )}
                    {sug.status === "ready" && (
                      <>
                        {sug.note && <div className="mt-1 text-xs text-violet-600">思路:{sug.note}</div>}
                        <div className="mt-2 text-sm text-stone-800 whitespace-pre-wrap bg-white rounded-lg border border-violet-100 p-2.5">{sug.reply}</div>
                        <div className="mt-2 flex gap-2">
                          <button
                            onClick={() => {
                              setMsgInput(sug.reply);
                              setSendAs("me");
                              setSug({ status: "idle", reply: "", note: "", error: "" });
                            }}
                            className="text-xs px-3 py-1.5 rounded-lg bg-violet-600 text-white hover:bg-violet-700"
                          >
                            填入输入框(可修改)
                          </button>
                          <button
                            onClick={() => setSug({ status: "idle", reply: "", note: "", error: "" })}
                            className="text-xs px-3 py-1.5 rounded-lg border border-violet-200 text-violet-600 hover:bg-violet-100"
                          >
                            忽略
                          </button>
                        </div>
                      </>
                    )}
                  </div>
                )}

                <div className="flex items-center gap-2 mb-2">
                  <button
                    onClick={genSuggestion}
                    disabled={sug.status === "loading"}
                    className="text-xs px-3 py-1.5 rounded-lg bg-violet-600 text-white hover:bg-violet-700 disabled:opacity-50"
                  >
                    {sug.status === "loading" ? "生成中…" : "AI销冠建议"}
                  </button>
                  <div className="ml-auto flex rounded-lg border border-stone-200 overflow-hidden text-xs">
                    <button
                      onClick={() => setSendAs("me")}
                      className={`px-2.5 py-1.5 ${sendAs === "me" ? "bg-emerald-600 text-white" : "bg-white text-stone-500 hover:bg-stone-50"}`}
                    >
                      我方发送
                    </button>
                    <button
                      onClick={() => setSendAs("cust")}
                      className={`px-2.5 py-1.5 ${sendAs === "cust" ? "bg-stone-700 text-white" : "bg-white text-stone-500 hover:bg-stone-50"}`}
                    >
                      客户消息(模拟)
                    </button>
                  </div>
                </div>

                <div className="flex gap-2">
                  <textarea
                    value={msgInput}
                    onChange={(e) => setMsgInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && !e.shiftKey) {
                        e.preventDefault();
                        send();
                      }
                    }}
                    rows={2}
                    placeholder={sendAs === "me" ? "输入回复,Enter发送(Shift+Enter换行)" : "以客户身份录入一条消息,用于模拟WhatsApp来信"}
                    className="flex-1 text-sm px-3 py-2 rounded-xl border border-stone-200 bg-white focus:outline-none focus:border-emerald-400 resize-none"
                  />
                  <button
                    onClick={send}
                    className={`self-end px-4 py-2 rounded-xl text-sm text-white ${sendAs === "me" ? "bg-emerald-600 hover:bg-emerald-700" : "bg-stone-700 hover:bg-stone-800"}`}
                  >
                    {sendAs === "me" ? "发送" : "录入"}
                  </button>
                </div>
              </div>
            </>
          )}
        </div>

        {active && (
          <div className="w-80 bg-white border-l border-stone-200 overflow-y-auto shrink-0">
            <div className="p-4 border-b border-stone-100">
              <div className="text-xs font-semibold text-stone-400 mb-2">客户档案</div>
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-400 w-12 shrink-0">电话</span>
                  <input
                    value={active.phone || ""}
                    onChange={(e) => updateCust(active.id, { phone: e.target.value })}
                    className="flex-1 text-sm px-2 py-1 rounded border border-stone-200 focus:outline-none focus:border-emerald-400"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-400 w-12 shrink-0">地区</span>
                  <input
                    value={active.region || ""}
                    onChange={(e) => updateCust(active.id, { region: e.target.value })}
                    className="flex-1 text-sm px-2 py-1 rounded border border-stone-200 focus:outline-none focus:border-emerald-400"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-400 w-12 shrink-0">阶段</span>
                  <select
                    value={active.stage}
                    onChange={(e) => updateCust(active.id, { stage: e.target.value })}
                    className="flex-1 text-sm px-2 py-1 rounded border border-stone-200 bg-white focus:outline-none focus:border-emerald-400"
                  >
                    {STAGES.map((s) => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-400 w-12 shrink-0">意向</span>
                  <div className="flex gap-1.5">
                    {INTENTS.map((i) => (
                      <button
                        key={i}
                        onClick={() => updateCust(active.id, { intent: i })}
                        className={`text-xs px-2 py-1 rounded border font-semibold ${active.intent === i ? INTENT_STYLE[i] : "bg-white text-stone-300 border-stone-200 hover:border-stone-300"}`}
                      >
                        {i}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="p-4 border-b border-stone-100">
              <div className="text-xs font-semibold text-stone-400 mb-2">标签</div>
              <div className="flex flex-wrap gap-1.5 mb-2">
                {(active.tags || []).map((t) => (
                  <span key={t} className="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200">
                    {t}
                    <button
                      onClick={() => updateCust(active.id, { tags: active.tags.filter((x) => x !== t) })}
                      className="text-emerald-400 hover:text-emerald-700"
                    >
                      ×
                    </button>
                  </span>
                ))}
                {(active.tags || []).length === 0 && <span className="text-xs text-stone-300">暂无标签</span>}
              </div>
              <div className="flex gap-2">
                <input
                  value={tagInput}
                  onChange={(e) => setTagInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      addTag();
                    }
                  }}
                  placeholder="输入标签,Enter添加"
                  className="flex-1 text-xs px-2 py-1.5 rounded border border-stone-200 focus:outline-none focus:border-emerald-400"
                />
                <button onClick={addTag} className="text-xs px-2.5 py-1.5 rounded bg-stone-100 hover:bg-stone-200 text-stone-600">
                  添加
                </button>
              </div>
            </div>

            <div className="p-4 border-b border-stone-100">
              <div className="text-xs font-semibold text-stone-400 mb-2">内部备注</div>
              <textarea
                value={active.notes || ""}
                onChange={(e) => updateCust(active.id, { notes: e.target.value })}
                rows={3}
                placeholder="客户背景、背调信息、注意事项…"
                className="w-full text-sm px-2.5 py-2 rounded-lg border border-stone-200 focus:outline-none focus:border-emerald-400 resize-none"
              />
            </div>

            <div className="p-4">
              <div className="flex items-center justify-between mb-2">
                <div className="text-xs font-semibold text-stone-400">跟进纪要</div>
                <button
                  onClick={genFollowUp}
                  disabled={fu.status === "loading"}
                  className="text-xs px-2.5 py-1 rounded-lg bg-violet-600 text-white hover:bg-violet-700 disabled:opacity-50"
                >
                  {fu.status === "loading" ? "生成中…" : "AI生成纪要"}
                </button>
              </div>

              {fu.status === "error" && <div className="mb-2 text-xs text-rose-600">{fu.error}</div>}
              {fu.status === "ready" && (
                <div className="mb-3 rounded-xl border border-violet-200 bg-violet-50 p-3">
                  <div className="text-xs font-semibold text-violet-700 mb-1.5">AI草稿(可编辑后保存)</div>
                  <textarea
                    value={fu.text}
                    onChange={(e) => setFu({ ...fu, text: e.target.value })}
                    rows={6}
                    className="w-full text-xs px-2.5 py-2 rounded-lg border border-violet-100 bg-white focus:outline-none focus:border-violet-400 resize-none whitespace-pre-wrap"
                  />
                  <div className="mt-2 flex gap-2">
                    <button onClick={saveFollowUp} className="text-xs px-3 py-1.5 rounded-lg bg-violet-600 text-white hover:bg-violet-700">
                      确认保存
                    </button>
                    <button
                      onClick={() => setFu({ status: "idle", text: "", error: "" })}
                      className="text-xs px-3 py-1.5 rounded-lg border border-violet-200 text-violet-600 hover:bg-violet-100"
                    >
                      放弃
                    </button>
                  </div>
                </div>
              )}

              <div className="space-y-2">
                {(active.followUps || []).length === 0 && fu.status !== "ready" && (
                  <div className="text-xs text-stone-300">暂无跟进记录,聊完点"AI生成纪要"自动填写</div>
                )}
                {(active.followUps || []).map((f) => (
                  <div key={f.id} className="rounded-lg border border-stone-200 bg-stone-50 p-2.5">
                    <div className="text-[10px] text-stone-400 mb-1">{fmtDate(f.ts)}</div>
                    <div className="text-xs whitespace-pre-wrap leading-relaxed">{f.content}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      {showSettings && (
        <div className="fixed inset-0 bg-black/30 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[85vh] overflow-y-auto p-5">
            <div className="text-sm font-semibold mb-1">知识库设置</div>
            <div className="text-xs text-stone-400 mb-4">这两份内容会在每次AI生成话术时被引用。把示例替换成你们的真实资料,建议质量会立刻不一样。</div>
            <div className="text-xs font-semibold text-stone-500 mb-1">产品知识库(FAQ / 价格政策 / 红线)</div>
            <textarea
              value={settingsDraft.productKb}
              onChange={(e) => setSettingsDraft({ ...settingsDraft, productKb: e.target.value })}
              rows={8}
              className="w-full text-xs px-3 py-2 rounded-lg border border-stone-200 focus:outline-none focus:border-emerald-400 resize-none mb-4"
            />
            <div className="text-xs font-semibold text-stone-500 mb-1">销冠打法与示范话术</div>
            <textarea
              value={settingsDraft.playbook}
              onChange={(e) => setSettingsDraft({ ...settingsDraft, playbook: e.target.value })}
              rows={8}
              className="w-full text-xs px-3 py-2 rounded-lg border border-stone-200 focus:outline-none focus:border-emerald-400 resize-none"
            />
            <div className="mt-4 flex justify-end gap-2">
              <button onClick={() => setShowSettings(false)} className="text-xs px-3 py-1.5 rounded-lg border border-stone-200 text-stone-500 hover:bg-stone-50">
                取消
              </button>
              <button
                onClick={() => {
                  persist({ ...data, settings: { ...settingsDraft } });
                  setShowSettings(false);
                  showToast("知识库已保存");
                }}
                className="text-xs px-4 py-1.5 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700"
              >
                保存
              </button>
            </div>
          </div>
        </div>
      )}

      {showAdd && (
        <div className="fixed inset-0 bg-black/30 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl w-full max-w-sm p-5">
            <div className="text-sm font-semibold mb-3">新增客户</div>
            <div className="space-y-2.5">
              <input
                value={addForm.name}
                onChange={(e) => setAddForm({ ...addForm, name: e.target.value })}
                placeholder="客户姓名(必填)"
                className="w-full text-sm px-3 py-2 rounded-lg border border-stone-200 focus:outline-none focus:border-emerald-400"
              />
              <input
                value={addForm.phone}
                onChange={(e) => setAddForm({ ...addForm, phone: e.target.value })}
                placeholder="WhatsApp号码"
                className="w-full text-sm px-3 py-2 rounded-lg border border-stone-200 focus:outline-none focus:border-emerald-400"
              />
              <input
                value={addForm.region}
                onChange={(e) => setAddForm({ ...addForm, region: e.target.value })}
                placeholder="地区/国家"
                className="w-full text-sm px-3 py-2 rounded-lg border border-stone-200 focus:outline-none focus:border-emerald-400"
              />
            </div>
            <div className="mt-4 flex justify-end gap-2">
              <button onClick={() => setShowAdd(false)} className="text-xs px-3 py-1.5 rounded-lg border border-stone-200 text-stone-500 hover:bg-stone-50">
                取消
              </button>
              <button onClick={addCustomer} className="text-xs px-4 py-1.5 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700">
                添加
              </button>
            </div>
          </div>
        </div>
      )}

      {toast && (
        <div className="fixed bottom-5 left-1/2 -translate-x-1/2 bg-stone-800 text-white text-xs px-4 py-2 rounded-full z-50">
          {toast}
        </div>
      )}
    </div>
  );
}
